mapper.select:
SELECT MAX(version) AS max_version
FROM vfs_revision
WHERE entry_id = #{entryId}

SELECT entry_id, version, content_hash, status, mtime_ms
   FROM vfs_revision
   WHERE entry_id = #{entryId} AND version = #{version}

SELECT 1 AS one FROM vfs_revision
   WHERE entry_id = #{entryId} AND version = #{version}
   LIMIT 1

SELECT status, content_hash FROM vfs_revision
   WHERE entry_id = #{entryId} AND version = #{version}
   LIMIT 1

mapper.update:
UPDATE vfs_revision
SET ref_count = ref_count + #{delta}- #{absDelta}
WHERE (entry_id, version) IN ((#{pair.entryId},#{pair.version})) AND ref_count >= #{absDelta}
